import { GoogleGenerativeAI } from "@google/generative-ai";
import { z } from "zod";

// --- Zod schemas ---

const ActivitySchema = z.object({
  name: z.string(),
  description: z.string(),
  startTime: z.string().optional(),
  durationMinutes: z.number().optional(),
  category: z.string().optional(),
  location: z.string().optional(),
  observations: z.string().optional(),
});

const DaySchema = z.object({
  dayNumber: z.number(),
  city: z.string(),
  title: z.string().optional(),
  notes: z.string().optional(),
  activities: z.array(ActivitySchema),
});

const ItineraryProposalSchema = z.object({
  days: z.array(DaySchema),
});

export type ActivityProposal = z.infer<typeof ActivitySchema>;
export type DayProposal = z.infer<typeof DaySchema>;
export type ItineraryProposal = z.infer<typeof ItineraryProposalSchema>;

export interface GenerateRequest {
  itineraryId: string;
  title: string;
  summary: string;
  destinationCities: string[];
  originCity?: string;
  startDate: string;
  endDate: string;
  travelerCount: number;
  tripType?: string;
  budget?: number;
  preferences?: string[];
  internalNotes?: string;
  dayCount: number;
}

const SYSTEM_PROMPT = `You are an expert travel planner for Jenny Adventures, a premium travel agency.
Your task is to generate detailed, inspiring, and practical travel itineraries.

Guidelines:
- Create day-by-day plans with 3–5 activities per day
- Balance sightseeing, dining, cultural experiences, and leisure
- Include practical details: locations, realistic durations, best times to visit
- Adapt the pace to the traveler count and trip type
- For budget trips, prefer free/low-cost activities and local dining
- Include categories: sightseeing, dining, transport, experience, accommodation, leisure
- Times in HH:MM format (24h), e.g. "09:00"
- Observations for insider tips, booking advice, or accessibility notes
- Respond ONLY with valid JSON matching the exact schema — no extra text, no markdown fences

Output schema:
{
  "days": [
    {
      "dayNumber": 1,
      "city": "string",
      "title": "optional theme for the day",
      "notes": "optional logistics note",
      "activities": [
        {
          "name": "string",
          "description": "string",
          "startTime": "HH:MM",
          "durationMinutes": 90,
          "category": "sightseeing|dining|transport|experience|accommodation|leisure",
          "location": "address or landmark",
          "observations": "optional tip"
        }
      ]
    }
  ]
}`;

export async function generateItinerary(
  request: GenerateRequest
): Promise<ItineraryProposal> {
  const apiKey = process.env.GATSBY_GEMINI_API_KEY;
  if (!apiKey) throw new Error("GATSBY_GEMINI_API_KEY is not set.");

  const genAI = new GoogleGenerativeAI(apiKey);
  const model = genAI.getGenerativeModel({
    model: "gemini-2.0-flash",
    systemInstruction: SYSTEM_PROMPT,
    generationConfig: {
      responseMimeType: "application/json",
      temperature: 1.0,
    },
  });

  const result = await model.generateContent(buildPrompt(request));
  const text = result.response.text().trim();

  try {
    const json = JSON.parse(text);
    return ItineraryProposalSchema.parse(json);
  } catch {
    throw new Error("AI returned an invalid response. Please try again.");
  }
}

function buildPrompt(data: GenerateRequest): string {
  const lines = [
    `Generate a ${data.dayCount}-day itinerary for the following trip:`,
    `Title: ${data.title}`,
    `Summary: ${data.summary}`,
    `Destinations: ${data.destinationCities.join(", ")}`,
    data.originCity ? `Origin: ${data.originCity}` : null,
    `Travel dates: ${data.startDate} to ${data.endDate}`,
    `Travelers: ${data.travelerCount}`,
    data.tripType ? `Trip type: ${data.tripType}` : null,
    data.budget ? `Budget (CAD): ${data.budget}` : null,
    data.preferences?.length ? `Preferences: ${data.preferences.join(", ")}` : null,
    data.internalNotes ? `Agent notes: ${data.internalNotes}` : null,
  ].filter(Boolean);

  return lines.join("\n");
}
