import React, { useState } from "react";
import type { Itinerary } from "../types";
import type {
  ActivityProposal,
  DayProposal,
  ItineraryProposal,
} from "../../../sessionServices/ai/aiItineraryService";
import { generateItinerary } from "../../../sessionServices/ai/aiItineraryService";
import { createDay } from "../../../sessionServices/itineraries/itineraryDaysService";
import { createActivity } from "../../../sessionServices/itineraries/activitiesService";
import { useAuth } from "../../auth/AuthContext";

interface Props {
  itineraryId: string;
  itinerary: Itinerary & { id: string };
  onSaved: () => void;
}

type State = "idle" | "generating" | "review" | "saving" | "done" | "error";

export function ItineraryAIGenerator({ itineraryId, itinerary, onSaved }: Props) {
  const { user } = useAuth();
  const [state, setState] = useState<State>("idle");
  const [dayCount, setDayCount] = useState(
    () => calcDayCount(itinerary.startDate, itinerary.endDate) || 3
  );
  const [proposal, setProposal] = useState<ItineraryProposal | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [error, setError] = useState<string | null>(null);

  async function handleGenerate() {
    setState("generating");
    setError(null);
    try {
      const result = await generateItinerary({
        itineraryId,
        title: itinerary.title,
        summary: itinerary.summary,
        destinationCities: itinerary.destinationCities,
        originCity: itinerary.originCity,
        startDate: tsToDateString(itinerary.startDate),
        endDate: tsToDateString(itinerary.endDate),
        travelerCount: itinerary.travelerCount,
        tripType: itinerary.tripType,
        budget: itinerary.budget,
        preferences: itinerary.preferences,
        internalNotes: itinerary.internalNotes,
        dayCount,
      });
      setProposal(result);
      // pre-select all activities
      const all = new Set<string>();
      result.days.forEach((d) =>
        d.activities.forEach((_, ai) => all.add(actKey(d.dayNumber, ai)))
      );
      setSelected(all);
      setState("review");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
      setState("error");
    }
  }

  async function handleSave() {
    if (!proposal || !user) return;
    setState("saving");
    try {
      const startMs = itinerary.startDate
        ? (itinerary.startDate as unknown as { toDate: () => Date }).toDate().getTime()
        : Date.now();

      for (const day of proposal.days) {
        const dayDate = new Date(startMs + (day.dayNumber - 1) * 86400000)
          .toISOString()
          .slice(0, 10);

        const dayId = await createDay({
          itineraryId,
          dayNumber: day.dayNumber,
          date: dayDate,
          city: day.city,
          title: day.title,
          notes: day.notes,
          createdBy: user.uid,
        });

        const approvedActivities = day.activities.filter((_, ai) =>
          selected.has(actKey(day.dayNumber, ai))
        );

        for (const act of approvedActivities) {
          await createActivity({
            itineraryId,
            itineraryDayId: dayId,
            dayNumber: day.dayNumber,
            city: day.city,
            name: act.name,
            description: act.description,
            startTime: act.startTime,
            durationMinutes: act.durationMinutes,
            category: act.category,
            location: act.location,
            observations: act.observations,
            createdBy: user.uid,
          });
        }
      }
      setState("done");
      onSaved();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Save failed");
      setState("error");
    }
  }

  function toggleActivity(dayNumber: number, actIdx: number) {
    const key = actKey(dayNumber, actIdx);
    setSelected((prev) => {
      const next = new Set(prev);
      next.has(key) ? next.delete(key) : next.add(key);
      return next;
    });
  }

  function toggleDay(day: DayProposal) {
    const keys = day.activities.map((_, ai) => actKey(day.dayNumber, ai));
    const allSelected = keys.every((k) => selected.has(k));
    setSelected((prev) => {
      const next = new Set(prev);
      if (allSelected) keys.forEach((k) => next.delete(k));
      else keys.forEach((k) => next.add(k));
      return next;
    });
  }

  if (state === "idle" || state === "error") {
    return (
      <div className="space-y-3">
        <div className="flex items-center gap-3">
          <label className="text-xs text-gray-600 font-medium">Days to generate</label>
          <input
            type="number"
            min={1}
            max={30}
            value={dayCount}
            onChange={(e) => setDayCount(Number(e.target.value))}
            className="w-16 rounded-lg border border-gray-300 px-2 py-1 text-sm"
          />
          <button
            onClick={handleGenerate}
            className="rounded-lg bg-indigo-600 px-4 py-1.5 text-xs font-medium text-white transition hover:bg-indigo-700"
          >
            ✨ Generate with AI
          </button>
        </div>
        {error && (
          <p className="text-xs text-red-600">{error}</p>
        )}
      </div>
    );
  }

  if (state === "generating") {
    return (
      <div className="flex items-center gap-3 py-4">
        <div className="h-5 w-5 animate-spin rounded-full border-4 border-indigo-200 border-t-indigo-600" />
        <p className="text-sm text-gray-600">Claude is building your itinerary…</p>
      </div>
    );
  }

  if (state === "saving") {
    return (
      <div className="flex items-center gap-3 py-4">
        <div className="h-5 w-5 animate-spin rounded-full border-4 border-gray-300 border-t-gray-800" />
        <p className="text-sm text-gray-600">Saving approved activities…</p>
      </div>
    );
  }

  if (state === "review" && proposal) {
    const totalActivities = proposal.days.reduce((n, d) => n + d.activities.length, 0);
    const approvedCount = selected.size;

    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <p className="text-xs text-gray-500">
            Review the proposal. Uncheck activities you don't want, then save.
            <span className="ml-2 font-medium text-gray-700">
              {approvedCount}/{totalActivities} approved
            </span>
          </p>
          <div className="flex gap-2">
            <button
              onClick={() => { setProposal(null); setState("idle"); }}
              className="rounded-lg border border-gray-300 px-3 py-1.5 text-xs font-medium text-gray-600 hover:bg-gray-50"
            >
              Discard
            </button>
            <button
              onClick={handleSave}
              disabled={approvedCount === 0}
              className="rounded-lg bg-gray-900 px-4 py-1.5 text-xs font-medium text-white transition hover:bg-gray-700 disabled:opacity-50"
            >
              Save {approvedCount} activit{approvedCount === 1 ? "y" : "ies"}
            </button>
          </div>
        </div>

        <div className="space-y-3">
          {proposal.days.map((day) => {
            const dayKeys = day.activities.map((_, ai) => actKey(day.dayNumber, ai));
            const allChecked = dayKeys.every((k) => selected.has(k));

            return (
              <div key={day.dayNumber} className="rounded-xl border border-gray-200 bg-white overflow-hidden">
                {/* Day header */}
                <div className="flex items-center gap-2 bg-gray-900 px-4 py-2">
                  <input
                    type="checkbox"
                    checked={allChecked}
                    onChange={() => toggleDay(day)}
                    className="h-3.5 w-3.5 rounded border-gray-400 accent-indigo-500"
                  />
                  <span className="flex h-5 w-5 items-center justify-center rounded-full bg-white text-xs font-bold text-gray-900">
                    {day.dayNumber}
                  </span>
                  <p className="text-sm font-semibold text-white">
                    {day.city}{day.title ? ` — ${day.title}` : ""}
                  </p>
                </div>

                {day.notes && (
                  <div className="border-b border-gray-100 bg-amber-50 px-4 py-1.5">
                    <p className="text-xs text-amber-800">{day.notes}</p>
                  </div>
                )}

                <div className="divide-y divide-gray-100">
                  {day.activities.map((act, ai) => {
                    const key = actKey(day.dayNumber, ai);
                    const checked = selected.has(key);
                    return (
                      <label
                        key={ai}
                        className={`flex cursor-pointer items-start gap-3 px-4 py-3 transition ${checked ? "" : "opacity-50"}`}
                      >
                        <input
                          type="checkbox"
                          checked={checked}
                          onChange={() => toggleActivity(day.dayNumber, ai)}
                          className="mt-0.5 h-3.5 w-3.5 rounded border-gray-300 accent-indigo-600"
                        />
                        <div className="flex-1 space-y-0.5">
                          <div className="flex flex-wrap items-center gap-2">
                            {act.startTime && (
                              <span className="font-mono text-xs text-gray-400">{act.startTime}</span>
                            )}
                            <span className="text-sm font-medium text-gray-900">{act.name}</span>
                            {act.category && (
                              <span className="rounded-full bg-gray-100 px-1.5 py-0.5 text-xs text-gray-500">
                                {act.category}
                              </span>
                            )}
                            {act.durationMinutes && (
                              <span className="text-xs text-gray-400">{act.durationMinutes} min</span>
                            )}
                          </div>
                          <p className="text-xs text-gray-600">{act.description}</p>
                          {act.location && (
                            <p className="text-xs text-gray-400">📍 {act.location}</p>
                          )}
                          {act.observations && (
                            <p className="text-xs italic text-gray-400">{act.observations}</p>
                          )}
                        </div>
                      </label>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  return null;
}

// --- helpers ---

function actKey(dayNumber: number, actIdx: number) {
  return `${dayNumber}_${actIdx}`;
}

function calcDayCount(startDate: unknown, endDate: unknown): number {
  try {
    const s = (startDate as { toDate: () => Date }).toDate();
    const e = (endDate as { toDate: () => Date }).toDate();
    return Math.max(1, Math.round((e.getTime() - s.getTime()) / 86400000) + 1);
  } catch {
    return 3;
  }
}

function tsToDateString(ts: unknown): string {
  try {
    return (ts as { toDate: () => Date }).toDate().toISOString().slice(0, 10);
  } catch {
    return new Date().toISOString().slice(0, 10);
  }
}
